/** 小老虎主題的背景：老虎身後的樹林與腳下的草地，同樣是像素圖，'.' 為透明。 */
import { spriteWidth } from './sprite'
import type { Sprite } from './sprite'
import type { Scene } from './theme'

/** 樹林圖磚：一棵圓樹、一棵松樹與一段空地，橫向無限重複。 */
export const TREES: Sprite = [
  '..GGG..........G........',
  '.GGLGG........GGG.......',
  'GGGGGLG.......GLG.......',
  'GLGGGGG......GGGGG......',
  '.GGGGG........GGG.......',
  '...B.........GGLGG......',
  '...B...........B........',
  '..BBB..........B........',
]

/** 草地圖磚：剛好一行文字（兩列像素）。 */
export const GRASS: Sprite = [
  '.g...H..g..g',
  'gggHgggggHgg',
]

/** 樹固定高度，不隨老虎縮放，當作比例尺。 */
export const TREE_HEIGHT = TREES.length

/** 頭頂留給打呼與蝴蝶的像素列數（一行文字）。 */
const HEADROOM = 2

/** 視差：遠處的樹走得慢，腳下的草跟老虎同速。 */
export const treeOffset = (x: number): number => Math.floor(x / 2)
export const grassOffset = (x: number): number => x

/** 從圖磚裁出指定寬度的一段；位移越大，畫面越往左移。 */
export const strip = (tile: Sprite, offset: number, width: number): Sprite => {
  const w = spriteWidth(tile)
  return tile.map(row =>
    Array.from({ length: width }, (_, i) => (w === 0 ? '.' : (row[(((i + offset) % w) + w) % w] ?? '.'))).join(''),
  )
}

/** 把 top 疊到 base 的 (x, y)：不透明像素蓋過去，透明的露出 base，超出範圍的裁掉。 */
export const overlay = (base: Sprite, top: Sprite, x: number, y: number): Sprite =>
  base.map((row, r) => {
    const src = top[r - y]
    if (src === undefined) return row
    const out = [...row]
    ;[...src].forEach((px, i) => {
      const c = x + i
      if (px !== '.' && c >= 0 && c < out.length) out[c] = px
    })
    return out.join('')
  })

const evenUp = (n: number): number => n + (n % 2)

/** 草以上的高度：樹與老虎取高的那個，補成偶數列讓半格字元對齊。 */
const bodyHeight = (poseHeight: number, withTrees: boolean): number =>
  Math.max(withTrees ? TREE_HEIGHT : 0, evenUp(poseHeight))

/** 整個場景佔幾行文字：頭頂一行＋樹或老虎＋草一行。 */
export const sceneLines = (poseHeight: number, withTrees: boolean): number =>
  (HEADROOM + bodyHeight(poseHeight, withTrees) + GRASS.length) / 2

/** 面板可見行數放得下清單（含標題）與含樹的場景時才畫樹。 */
export const fitsTrees = (bodyRows: number, listRows: number, poseHeight: number): boolean =>
  listRows + sceneLines(poseHeight, true) <= bodyRows

/** 背景、老虎、草地合成一張圖。老虎與樹都站在草上。 */
export const composeScene = (o: { pose: Sprite; x: number; columns: number; withTrees: boolean }): Scene => {
  const height = HEADROOM + bodyHeight(o.pose.length, o.withTrees)
  const sky: Sprite = Array.from({ length: height }, () => '.'.repeat(o.columns))
  const woods = o.withTrees ? overlay(sky, strip(TREES, treeOffset(o.x), o.columns), 0, height - TREE_HEIGHT) : sky
  const top = height - o.pose.length
  const sprite = [...overlay(woods, o.pose, o.x, top), ...strip(GRASS, grassOffset(o.x), o.columns)]
  return { sprite, top }
}

files.hooks/stars.ts:
/**
 * 綠雲與愛心主題的背景：閃爍的星空。星星是文字符號，蓋在場景上。
 * 位置由面板尺寸決定的固定種子產生，同尺寸下每格都在同一個位置；不跟著角色捲動。
 */
import type { Mark } from './frame'

export type Star = {
  line: number
  col: number
  glyph: '·' | '✦' | '✧'
  color: 'yellowBright' | 'whiteBright'
  /** 會不會閃爍；不閃的星一直亮著。 */
  twinkles: boolean
  /** 閃爍的起始相位，讓星星不會同時一起閃。 */
  phase: number
}

/** 平均每幾格放一顆星。 */
const CELLS_PER_STAR = 12

const GLYPHS: readonly Star['glyph'][] = ['·', '✦', '✧']
const COLORS: readonly Star['color'][] = ['yellowBright', 'whiteBright']

/** 閃爍一輪：亮 → 暗 → 消失 → 暗。每步維持 TWINKLE_FRAMES 格。 */
export const TWINKLE_STEPS = 4
const TWINKLE_FRAMES = 2

/** 固定種子的亂數（mulberry32）：同一個種子永遠產生同一串數字。 */
export const seeded = (seed: number): (() => number) => {
  let a = seed >>> 0
  return () => {
    a = (a + 0x6d2b79f5) >>> 0
    let t = a
    t = Math.imul(t ^ (t >>> 15), t | 1)
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61)
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

/** 面板 columns 欄、lines 行的星空：約每 12 格一顆，一半會閃。 */
export const starField = (columns: number, lines: number): Star[] => {
  const random = seeded(columns * 1009 + lines)
  const pick = <T>(xs: readonly T[]): T => xs[Math.floor(random() * xs.length)] as T
  const count = Math.floor((columns * lines) / CELLS_PER_STAR)
  const taken = new Set<string>()
  const stars: Star[] = []
  for (let i = 0; i < count; i++) {
    const line = Math.floor(random() * lines)
    const col = Math.floor(random() * columns)
    const glyph = pick(GLYPHS)
    const color = pick(COLORS)
    const phase = Math.floor(random() * TWINKLE_STEPS)
    if (taken.has(`${line},${col}`)) continue
    taken.add(`${line},${col}`)
    stars.push({ line, col, glyph, color, twinkles: stars.length % 2 === 0, phase })
  }
  return stars
}

/** 第 frame 格時這顆星的樣子；空字串表示這格看不到。 */
export const starGlyph = (star: Star, frame: number): string => {
  if (!star.twinkles) return star.glyph
  const step = (Math.floor(frame / TWINKLE_FRAMES) + star.phase) % TWINKLE_STEPS
  return [star.glyph, '·', '', '·'][step] ?? star.glyph
}

/** 星星換成文字符號；blocked(line, col) 為真的格子（角色、對話框）不放。 */
export const starMarks = (stars: readonly Star[], frame: number, blocked: (line: number, col: number) => boolean): Mark[] =>
  stars.flatMap(star => {
    const text = starGlyph(star, frame)
    return text === '' || blocked(star.line, star.col) ? [] : [{ line: star.line, col: star.col, text, color: star.color }]
  })

